const CONFIG=window.VIVA_CONFIG||{};
const SB=CONFIG.supabaseUrl||''; const KEY=CONFIG.supabaseAnonKey||'';
const AUTH='vivaBkoAuthV1';
let session=null, dashboardState=null, orders=[], clients=[], rules=[];
let currentView='dashboard', tvTimer=null, tvZoom=1;
let currentCnpjData=null, commercialItemSeq=0, reportTab='all', pendingDeliveryFilter='';
const PRODUCT_SEED=['MÓVEL','TI','APARELHO','AVANÇADO','BANDA LARGA'];
const SUBPRODUCT_SEED=['alta','link dedicado','MIGRAÇÃO','MIGRAÇÃO LINA/VN','MIGRAÇÃOLINA/VN','PF/PJ','PORTABILIDADE','SIP','UPGRADE'];
const SUBITEM_SEED=['MDM','Pacote dados','Travel','1GB','3GB','6GB','10GB','15GB','20GB','25GB','30GB','40GB','50GB','60GB','80GB','100GB','400MBPS','500MBPS','600MBPS','700MBPS'];
const BKO_RESPONSAVEIS=['Guilherme Chagas','Guilherme Aparecido'];
const DRAFT_PREFIX='vivaBkoDraftV18_';
function applyTvZoom(){const el=document.querySelector('.tv-shell');if(el)el.style.zoom=String(tvZoom);const lbl=document.getElementById('tvZoomLabel');if(lbl)lbl.textContent=Math.round(tvZoom*100)+'%'}
function changeTvZoom(delta){tvZoom=Math.max(.7,Math.min(1.4,Math.round((tvZoom+delta)*10)/10));applyTvZoom()}
function resetTvZoom(){tvZoom=1;applyTvZoom()}
const STATUSES=['ANÁLISE BKO','ANÁLISE DE CRÉDITO','ANÁLISE DE FRAUDE','AGUARDANDO INFORMAÇÃO','EM ANDAMENTO','APROVADO','REPROVADO CRÉDITO','REPROVADO FRAUDE','CANCELADO'];
const DELIVERY=['','AGUARDANDO INSTALAÇÃO','AG. INSTALAÇÃO','AG. ENTREGA','F1 GANHA','LOGÍSTICA CONCLUÍDA','CONCLUÍDO','CANCELADO'];
const app=document.getElementById('app');
function token(){return session?.access_token||''} function uid(){return session?.user?.id||''}
function toast(m){const t=document.createElement('div');t.className='toast';t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),2300)}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function norm(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().replace(/\s+/g,' ').toLowerCase()}
function money(v){return Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}

function parseNum(v){if(typeof v==='number')return Number.isFinite(v)?v:0;let x=String(v??'').trim().replace(/R\$/gi,'').replace(/\s/g,'');if(!x)return 0;if(x.includes(',')&&x.includes('.'))x=x.replace(/\./g,'').replace(',','.');else if(x.includes(','))x=x.replace(',','.');const n=Number(x);return Number.isFinite(n)?n:0}
function asArray(v){if(Array.isArray(v))return v.filter(Boolean);if(v==null||v==='')return[];return String(v).split(/[,;|]/).map(x=>x.trim()).filter(Boolean)}
function uniq(vals){return [...new Set(vals.filter(Boolean).map(x=>String(x).trim()).filter(Boolean))]}
function isAwaitingInstallation(o){const e=norm(o?.status_entrega);return e==='aguardando instalacao'||e==='ag. instalacao'||e.includes('aguardando instalacao')}
function dynamicProductOptions(){return [...PRODUCT_SEED]}
function dynamicSubProductOptions(){return [...SUBPRODUCT_SEED]}
function dynamicSubItemOptions(){return [...SUBITEM_SEED]}
function renderMultiSelect(id,options,selected=[],placeholder='Selecionar'){selected=asArray(selected);const canonical=new Map(options.map(o=>[norm(o),o]));selected=selected.map(v=>canonical.get(norm(v))||v);const merged=[...options,...selected];const seen=new Set();options=merged.filter(v=>{const k=norm(v);if(!k||seen.has(k))return false;seen.add(k);return true});selected=[...new Map(selected.map(v=>[norm(v),v])).values()];const selNorm=new Set(selected.map(norm));const label=selected.length?selected.join(', '):placeholder;return `<div class="multi-select" id="${id}"><button type="button" class="multi-select-toggle" onclick="toggleMultiSelect('${id}',event)"><span>${esc(label)}</span><b>⌄</b></button><div class="multi-select-menu"><input type="search" placeholder="Pesquisar" oninput="filterMultiSelect('${id}',this.value)"><div class="multi-select-options">${options.map(o=>`<label data-ms-opt="${esc(norm(o))}"><input type="checkbox" value="${esc(o)}" ${selNorm.has(norm(o))?'checked':''} onchange="multiSelectChanged('${id}')"><span>${esc(o)}</span></label>`).join('')}</div></div></div>`}
function toggleMultiSelect(id,e){e?.stopPropagation();document.querySelectorAll('.multi-select.open').forEach(x=>{if(x.id!==id)x.classList.remove('open')});document.getElementById(id)?.classList.toggle('open')}
function filterMultiSelect(id,q){const n=norm(q);document.querySelectorAll(`#${CSS.escape(id)} [data-ms-opt]`).forEach(x=>x.style.display=!n||x.dataset.msOpt.includes(n)?'flex':'none')}
function multiSelectValues(id){return [...(document.querySelectorAll(`#${CSS.escape(id)} input[type=checkbox]:checked`)||[])].map(x=>x.value)}
function multiSelectChanged(id){const box=document.getElementById(id);if(!box)return;const vals=multiSelectValues(id);const span=box.querySelector('.multi-select-toggle span');if(span)span.textContent=vals.length?vals.join(', '):'Selecionar';scheduleDraftSave()}
document.addEventListener('click',e=>{if(!e.target.closest('.multi-select'))document.querySelectorAll('.multi-select.open').forEach(x=>x.classList.remove('open'))})
window.addEventListener('pagehide',()=>saveDraftNow());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveDraftNow()})
function itemIsMigration(it){return [...asArray(it.produto),...asArray(it.sub_produto),...asArray(it.sub_item)].some(x=>norm(x).includes('migracao'))}
function dashboardRevenueForItem(it){return itemIsMigration(it)?parseNum(it.delta):parseNum(it.valor_contrato)}
function commercialItemsFromOrder(o){if(Array.isArray(o?.itens_comerciais)&&o.itens_comerciais.length)return o.itens_comerciais;if(typeof o?.itens_comerciais==='string'){try{const a=JSON.parse(o.itens_comerciais);if(Array.isArray(a)&&a.length)return a}catch{}}if(!o)return[];return [{debito_automatico:o.debito_automatico||'',quality:o.quality||'',vencimento:o.vencimento||'',tipo_cliente:o.tipo_cliente||'',produto:uniq([...asArray(o.produto_planilha||o.modalidade),...asArray(o.tronco)]),sub_produto:asArray(o.sub_produto||o.subproduto),sub_item:asArray(o.sub_item),delta:o.delta||'',outro:o.outro||'',quantidade:o.quantidade??1,valor_unitario:o.valor_unitario??'',valor_contrato:o.valor_contrato??0,dashboard_product:o.dashboard_product||'',subir_dashboard:o.subir_dashboard===true||!!o.dashboard_synced_at}]}
function draftKey(){return DRAFT_PREFIX+(uid()||'anon')}
function getDraft(){try{return JSON.parse(localStorage.getItem(draftKey())||'null')}catch{return null}}
function clearDraft(){localStorage.removeItem(draftKey())}
let draftTimer=null;
function scheduleDraftSave(){clearTimeout(draftTimer);draftTimer=setTimeout(saveDraftNow,250)}
function saveDraftNow(){if(currentView!=='novo'||!document.getElementById('orderForm'))return;try{const data=collectFormState(true);localStorage.setItem(draftKey(),JSON.stringify({savedAt:new Date().toISOString(),data}));const el=document.getElementById('draftStatus');if(el)el.textContent='Rascunho salvo automaticamente ✓'}catch(e){console.warn('draft',e)}}
function discardDraft(){if(confirm('Descartar o rascunho deste pedido?')){clearDraft();renderForm(null,true);toast('Rascunho descartado')}}
function formatCnpjInput(el){let v=cleanCnpj(el.value).slice(0,14);v=v.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\/\d{4})(\d)/,'$1-$2');el.value=v;if(cleanCnpj(v).length===14)lookupCnpj()}
function renderCnpjDetails(d){const box=document.getElementById('cnpjDetails');if(!box)return;if(!d){box.innerHTML='';return}const rows=[['Nome fantasia',d.nome_fantasia],['Situação',d.situacao],['Abertura',d.abertura],['CEP',d.cep],['Endereço',d.endereco],['Bairro',d.bairro],['Cidade',d.cidade],['UF',d.uf],['Telefone',d.telefone],['E-mail',d.email],['CNAE',d.cnae],['Porte',d.porte],['Natureza jurídica',d.natureza_juridica],['Matriz/Filial',d.matriz_filial],['Representante',d.representante]].filter(x=>x[1]);box.innerHTML=rows.length?`<div class="cnpj-details">${rows.map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}</div>`:''}

function saveSession(s){session=s;if(s)localStorage.setItem(AUTH,JSON.stringify(s));else localStorage.removeItem(AUTH)}
function loadSession(){try{session=JSON.parse(localStorage.getItem(AUTH)||'null')}catch{session=null}}
async function api(path,opt={}){const headers={apikey:KEY,Authorization:`Bearer ${token()||KEY}`,'Content-Type':'application/json',...(opt.headers||{})};const r=await fetch(`${SB}${path}`,{...opt,headers});if(r.status===401&&session?.refresh_token){if(await refresh()){return api(path,opt)}}if(!r.ok){let b={};try{b=await r.json()}catch{};throw new Error(b.message||b.msg||b.error_description||`Erro ${r.status}`)}if(r.status===204)return null;const txt=await r.text();return txt?JSON.parse(txt):null}
async function refresh(){try{const r=await fetch(`${SB}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok)throw 0;saveSession(await r.json());return true}catch{saveSession(null);return false}}
async function login(e){e.preventDefault();loginError.textContent='';try{const r=await fetch(`${SB}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({email:loginEmail.value.trim(),password:loginPassword.value})});const b=await r.json();if(!r.ok)throw new Error(b.error_description||'E-mail ou senha inválidos');saveSession(b);await boot()}catch(err){loginError.textContent=err.message}}
function logout(){saveSession(null);renderLogin()}
function renderLogin(){app.innerHTML=`<div class="login-shell"><div class="login-card"><img src="logo-viva.png"><h1>Sistema de Alimentação BKO</h1><p>Cadastre e acompanhe pedidos. Somente pedidos aprovados são enviados ao Dashboard Viva Conecta.</p><form onsubmit="login(event)"><label>E-mail</label><input id="loginEmail" type="email" required><label>Senha</label><input id="loginPassword" type="password" required><div id="loginError" class="login-error"></div><button class="btn primary login-btn">Entrar</button></form></div></div>`}
async function loadDashboard(){const rows=await api('/rest/v1/viva_state?id=eq.1&select=data');dashboardState=rows?.[0]?.data||null}
async function loadAll(){await Promise.all([loadDashboard(),loadOrders(),loadClients(),loadRules()])}
async function loadOrders(){orders=await api('/rest/v1/bko_orders?select=*&order=created_at.desc')||[]}
async function loadClients(){clients=await api('/rest/v1/bko_clients?select=*&order=razao_social.asc')||[]}
async function loadRules(){rules=await api('/rest/v1/bko_rules?select=*&order=modalidade.asc')||[]}
function consultants(){return (dashboardState?.people||[]).filter(p=>p.active!==false)}
function products(){return dashboardState?.products||[]}
async function boot(){if(!SB||!KEY){app.innerHTML='<div class="empty">Configuração do Supabase não encontrada.</div>';return}loadSession();if(!session){renderLogin();return}try{await loadAll();render()}catch(e){console.error(e);if(String(e.message).includes('bko_orders')){app.innerHTML=`<div class="login-shell"><div class="login-card"><img src="logo-viva.png"><h1>Falta preparar o banco</h1><p>O sistema abriu, mas as tabelas do BKO ainda não existem. Execute o arquivo <b>BKO-SETUP.sql</b> no SQL Editor do mesmo Supabase usado pelo Dashboard.</p><button class="btn" onclick="logout()">Sair</button></div></div>`}else{toast(e.message);renderLogin()}}}
function nav(label,view){return `<button class="${currentView===view?'active':''}" onclick="go('${view}')">${label}</button>`}
function shell(inner){return `<div class="shell"><aside class="sidebar"><div class="brand"><img src="logo-viva.png"></div><div class="nav">${nav('Dashboard BKO','dashboard')}${nav('Modo TV','tv')}${nav('Pedidos','pedidos')}${nav('Novo pedido','novo')}${nav('Relatórios','relatorios')}${nav('Clientes','clientes')}${nav('Regras automáticas','regras')}</div><div class="sidebar-foot">Viva Conecta Telecom<br>Supabase conectado<br>Dashboard comercial preservado</div></aside><main class="content"><div class="topbar"><div><h1>Sistema BKO</h1><p>Uma entrada de informação → operação e Dashboard sincronizados.</p></div><div class="top-actions"><span class="pill"><i class="dot"></i>Online</span><button class="btn" onclick="logout()">Sair</button></div></div>${inner}</main></div>`}
function go(v){if(currentView==='novo')saveDraftNow();if(tvTimer){clearInterval(tvTimer);tvTimer=null}currentView=v;render()}
function statusClass(s){s=norm(s);if(s==='aprovado')return'aprovado';if(s.includes('reprov')||s.includes('cancel'))return'reprovado';if(s.includes('andamento')||s.includes('analise')||s.includes('aguard'))return'andamento';return'outro'}
function render(){if(currentView==='tv')return renderTvDashboard();if(currentView==='dashboard')return renderDashboardBko();if(currentView==='novo')return renderForm();if(currentView==='relatorios')return renderReports();if(currentView==='clientes')return renderClients();if(currentView==='regras')return renderRules();renderOrders()}
function statusCounts(list){
  const c={total:list.length,analiseBko:0,credito:0,fraude:0,aguardando:0,andamento:0,aprovado:0,reprovado:0,cancelado:0,concluido:0,synced:0,aguardandoInstalacao:0};
  for(const o of list){const st=norm(o.status_pedido),ent=norm(o.status_entrega);if(st==='analise bko')c.analiseBko++;if(st==='analise de credito')c.credito++;if(st==='analise de fraude')c.fraude++;if(st==='aguardando informacao')c.aguardando++;if(st==='em andamento')c.andamento++;if(st==='aprovado')c.aprovado++;if(st.includes('reprov'))c.reprovado++;if(st.includes('cancel'))c.cancelado++;if(ent==='concluido')c.concluido++;if(isAwaitingInstallation(o))c.aguardandoInstalacao++;if(o.dashboard_synced_at)c.synced++;}
  return c;
}
function renderDashboardBko(){
  const c=statusCounts(orders), uniqueClients=new Set(orders.map(o=>cleanCnpj(o.cnpj)).filter(Boolean)).size;
  const sellers=groupSummary(orders,o=>o.consultor).slice(0,8);
  const recent=orders.slice(0,8);
  app.innerHTML=shell(`<div class="section-title dashboard-title"><div><h2>Dashboard BKO</h2><p>Visão operacional de todos os pedidos, inclusive os que ainda não foram aprovados.</p></div><div class="dashboard-actions"><button class="btn" onclick="go('tv')">Abrir modo TV</button><button class="btn primary" onclick="go('novo')">+ Novo pedido</button></div></div>
  <div class="grid bko-status-grid">
    <div class="card status-card"><small>Total de pedidos</small><strong>${c.total}</strong></div>
    <div class="card status-card warn"><small>Análise BKO</small><strong>${c.analiseBko}</strong></div>
    <div class="card status-card warn"><small>Análise de crédito</small><strong>${c.credito}</strong></div>
    <div class="card status-card warn"><small>Análise de fraude</small><strong>${c.fraude}</strong></div>
    <div class="card status-card info"><small>Aguardando informação</small><strong>${c.aguardando}</strong></div>
    <div class="card status-card info"><small>Em andamento</small><strong>${c.andamento}</strong></div>
    <div class="card status-card ok"><small>Aprovados</small><strong>${c.aprovado}</strong></div>
    <div class="card status-card install clickable" onclick="showAwaitingInstallation()"><small>Aguardando Instalação</small><strong>${c.aguardandoInstalacao}</strong><em>Ver pedidos</em></div>
    <div class="card status-card bad"><small>Reprovados / Cancelados</small><strong>${c.reprovado+c.cancelado}</strong></div>
  </div>
  <div class="grid mini-kpis"><div class="card mini-kpi"><small>Clientes</small><b>${uniqueClients}</b></div><div class="card mini-kpi"><small>Enviados ao Dashboard</small><b>${c.synced}</b></div><div class="card mini-kpi"><small>Concluídos</small><b>${c.concluido}</b></div></div>
  <div class="dashboard-two"><div class="card section-card"><div class="section-title"><div><h2>Pedidos recentes</h2><p>Últimas movimentações cadastradas.</p></div><button class="btn" onclick="go('pedidos')">Ver todos</button></div><div class="table-wrap"><table class="table dashboard-table"><thead><tr><th>Cliente</th><th>Consultor</th><th>Status</th></tr></thead><tbody>${recent.length?recent.map(o=>`<tr class="order-row" onclick="editOrder('${o.id}')"><td><b>${esc(o.razao_social)}</b><br><small>${esc(o.numero_pedido||'')}</small></td><td>${esc(o.consultor)}</td><td><span class="badge ${statusClass(o.status_pedido)}">${esc(o.status_pedido)}</span></td></tr>`).join(''):'<tr><td colspan="3"><div class="empty">Nenhum pedido cadastrado.</div></td></tr>'}</tbody></table></div></div>
  <div class="card section-card"><div class="section-title"><div><h2>Por consultor</h2><p>Volume de pedidos e aprovados.</p></div></div><div class="table-wrap"><table class="table dashboard-table"><thead><tr><th>Consultor</th><th>Pedidos</th><th>Aprovados</th></tr></thead><tbody>${sellers.length?sellers.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.pedidos}</td><td>${x.aprovados}</td></tr>`).join(''):'<tr><td colspan="3"><div class="empty">Sem dados.</div></td></tr>'}</tbody></table></div></div></div>`);
}
function pct(part,total){return total?Math.round((part/total)*100):0}
function renderStatusBar(label,value,total,cls=''){const w=pct(value,total);return `<div class="tv-status-row"><div class="tv-status-head"><span>${esc(label)}</span><b>${value}</b></div><div class="tv-track"><i class="${cls}" style="width:${w}%"></i></div></div>`}
function tvClock(){const n=new Date();return n.toLocaleString('pt-BR',{weekday:'long',day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit'}).replace(/^./,x=>x.toUpperCase())}
async function refreshTv(){try{await loadOrders();if(currentView==='tv')renderTvDashboard(false)}catch(e){console.error(e)}}
function renderTvDashboard(startTimer=true){
  const c=statusCounts(orders), uniqueClients=new Set(orders.map(o=>cleanCnpj(o.cnpj)).filter(Boolean)).size;
  const sellers=groupSummary(orders,o=>o.consultor).slice(0,6);
  const attention=orders.filter(o=>{const s=norm(o.status_pedido);return s.includes('analise')||s.includes('aguardando')||s==='em andamento'}).slice(0,7);
  const approvedRate=pct(c.aprovado,c.total), pending=c.analiseBko+c.credito+c.fraude+c.aguardando+c.andamento;
  app.innerHTML=`<div class="tv-shell"><header class="tv-head"><div class="tv-brand"><img src="logo-viva.png"><div><span>CENTRAL OPERACIONAL</span><h1>Dashboard BKO</h1></div></div><div class="tv-head-right"><div><b>Atualização automática</b><span id="tvClock">${tvClock()}</span></div><div class="tv-zoom" aria-label="Tamanho do painel"><button type="button" onclick="changeTvZoom(-0.1)" title="Diminuir">−</button><button type="button" id="tvZoomLabel" onclick="resetTvZoom()" title="Voltar para 100%">100%</button><button type="button" onclick="changeTvZoom(0.1)" title="Aumentar">+</button></div><button class="tv-exit" onclick="go('dashboard')">Sair do modo TV</button></div></header>
  <section class="tv-hero"><div><span class="tv-eyebrow">VISÃO GERAL DA OPERAÇÃO</span><h2>${c.total} pedidos acompanhados</h2><p>Atualização automática a cada 30 segundos • o envio ao Dashboard comercial é definido individualmente em cada pedido/produto: SIM ou NÃO.</p></div><div class="tv-rate"><strong>${approvedRate}%</strong><span>taxa de aprovação</span></div></section>
  <section class="tv-kpis">
    <article class="tv-kpi total"><span>Total de pedidos</span><strong>${c.total}</strong><small>${uniqueClients} cliente(s)</small></article>
    <article class="tv-kpi warning"><span>Em análise / andamento</span><strong>${pending}</strong><small>${c.credito} em crédito • ${c.analiseBko} no BKO</small></article>
    <article class="tv-kpi success"><span>Aprovados</span><strong>${c.aprovado}</strong><small>${c.synced} enviados ao Dashboard</small></article>
    <article class="tv-kpi danger"><span>Reprovados / cancelados</span><strong>${c.reprovado+c.cancelado}</strong><small>${c.reprovado} reprovados • ${c.cancelado} cancelados</small></article>
  </section>
  <section class="tv-grid">
    <article class="tv-panel status-panel"><div class="tv-panel-title"><div><span>PIPELINE</span><h3>Pedidos por status</h3></div><b>${c.total}</b></div>
      ${renderStatusBar('Análise BKO',c.analiseBko,c.total,'amber')}${renderStatusBar('Análise de crédito',c.credito,c.total,'amber')}${renderStatusBar('Análise de fraude',c.fraude,c.total,'orange')}${renderStatusBar('Aguardando informação',c.aguardando,c.total,'blue')}${renderStatusBar('Em andamento',c.andamento,c.total,'blue')}${renderStatusBar('Aprovados',c.aprovado,c.total,'green')}
    </article>
    <article class="tv-panel"><div class="tv-panel-title"><div><span>DESTAQUES</span><h3>Por consultor</h3></div><b>${sellers.length}</b></div><div class="tv-ranking">${sellers.length?sellers.map((x,i)=>`<div class="tv-rank"><span class="tv-pos">${i+1}º</span><div><b>${esc(x.name)}</b><small>${x.aprovados} aprovado(s) de ${x.pedidos}</small></div><strong>${x.pedidos}</strong></div>`).join(''):'<div class="tv-empty">Sem dados ainda.</div>'}</div></article>
    <article class="tv-panel attention-panel"><div class="tv-panel-title"><div><span>ATENÇÃO</span><h3>Pedidos em acompanhamento</h3></div><b>${attention.length}</b></div><div class="tv-attention-list">${attention.length?attention.map(o=>`<div class="tv-attention"><div><b>${esc(o.razao_social)}</b><small>${esc(o.consultor)} • ${esc(o.numero_pedido||'Sem nº pedido')}</small></div><span class="tv-status-pill ${statusClass(o.status_pedido)}">${esc(o.status_pedido)}</span></div>`).join(''):'<div class="tv-empty">Nenhum pedido pendente no momento.</div>'}</div></article>
  </section><footer class="tv-footer"><span>Viva Conecta • Sistema BKO</span><span>Operação acompanhada em tempo real</span></footer></div>`;
  applyTvZoom();
  if(startTimer&&!tvTimer)tvTimer=setInterval(refreshTv,30000);
}

function showAwaitingInstallation(){pendingDeliveryFilter='AGUARDANDO INSTALAÇÃO';currentView='pedidos';renderOrders()}
function orderFilteredList(){const q=norm(document.getElementById('q')?.value),st=norm(document.getElementById('statusFilter')?.value),ent=norm(document.getElementById('deliveryFilter')?.value);return orders.filter(o=>(!st||norm(o.status_pedido)===st)&&(!ent||(ent==='aguardando instalacao'?isAwaitingInstallation(o):norm(o.status_entrega)===ent))&&(!q||[o.cnpj,o.razao_social,o.consultor,o.numero_pedido,o.modalidade,o.equipe,o.status_entrega].some(v=>norm(v).includes(q))))}
function orderFilterSummaryHtml(list){const c=statusCounts(list);return `<div class="filter-summary"><span><b>${c.total}</b> pedido(s)</span><span>Aprovados <b>${c.aprovado}</b></span><span>Aguardando instalação <b>${c.aguardandoInstalacao}</b></span><span>Análise BKO <b>${c.analiseBko}</b></span><span>Crédito <b>${c.credito}</b></span><span>Fraude <b>${c.fraude}</b></span><span>Em andamento <b>${c.andamento}</b></span><span>Reprovados <b>${c.reprovado}</b></span><span>Cancelados <b>${c.cancelado}</b></span></div>`}
function renderOrders(){const c=statusCounts(orders);const pending=orders.length-c.aprovado-c.reprovado-c.cancelado;const deliveryPreset=pendingDeliveryFilter;pendingDeliveryFilter='';app.innerHTML=shell(`<div class="grid kpis"><div class="card kpi"><small>Total de pedidos</small><strong>${orders.length}</strong></div><div class="card kpi"><small>Em andamento</small><strong>${pending}</strong></div><div class="card kpi"><small>Aguardando instalação</small><strong>${c.aguardandoInstalacao}</strong></div><div class="card kpi"><small>Enviados ao Dashboard</small><strong>${c.synced}</strong></div></div><div class="notice"><b>Regra ativa:</b> o envio ao Dashboard é definido individualmente em cada <b>Pedido/Produto</b> em <b>Adicionar ao Dashboard? SIM / NÃO</b>. O status do pedido e o status de entrega não controlam mais esse envio. Em <b>Migração</b>, continua subindo somente o valor do <b>Delta</b>.</div><div class="card toolbar"><div class="toolbar-left"><input class="search" id="q" placeholder="Buscar CNPJ, cliente, consultor ou nº pedido" oninput="filterOrders()"><select id="statusFilter" class="btn" onchange="filterOrders()"><option value="">Todos os status</option>${STATUSES.map(s=>`<option>${s}</option>`).join('')}</select><select id="deliveryFilter" class="btn" onchange="filterOrders()"><option value="">Todos os andamentos</option><option value="AGUARDANDO INSTALAÇÃO" ${deliveryPreset?'selected':''}>Aguardando Instalação</option>${DELIVERY.filter(x=>x&&norm(x)!=='aguardando instalacao'&&norm(x)!=='ag. instalacao').map(x=>`<option>${x}</option>`).join('')}</select></div><div class="toolbar-right"><button class="btn primary" onclick="go('novo')">+ Novo pedido</button></div></div><div id="orderFilterSummary">${orderFilterSummaryHtml(deliveryPreset?orders.filter(isAwaitingInstallation):orders)}</div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Cliente</th><th>CNPJ</th><th>Consultor</th><th>Produto</th><th>Valor</th><th>Status</th><th>Instalação/Entrega</th><th>Dashboard</th><th>Ações</th></tr></thead><tbody id="ordersBody">${ordersRows(deliveryPreset?orders.filter(isAwaitingInstallation):orders)}</tbody></table></div></div>`)}
function ordersRows(list){if(!list.length)return'<tr><td colspan="10"><div class="empty">Nenhum pedido cadastrado ainda.</div></td></tr>';return list.map(o=>`<tr class="order-row" role="button" tabindex="0" onclick="editOrder('${o.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();editOrder('${o.id}')}\"><td>${o.data_venda?new Date(o.data_venda+'T12:00:00').toLocaleDateString('pt-BR'):'-'}</td><td><b>${esc(o.razao_social)}</b><br><small>${esc(o.numero_pedido||'')}</small></td><td>${esc(o.cnpj)}</td><td>${esc(o.consultor)}<br><small>${esc(o.equipe||'')}</small></td><td>${esc(o.produto_planilha||o.modalidade||'')}<br><small>${commercialItemsFromOrder(o).length>1?commercialItemsFromOrder(o).length+' produtos':esc(o.dashboard_product||o.produto||'')}</small></td><td>${money(o.valor_contrato)}</td><td><span class="badge ${statusClass(o.status_pedido)}">${esc(o.status_pedido)}</span></td><td>${isAwaitingInstallation(o)?'<span class="badge andamento">Aguardando Instalação</span>':esc(o.status_entrega||'-')}</td><td>${o.dashboard_synced_at?'<span class="sync">Enviado ✓</span>':'-'}</td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" onclick="event.stopPropagation();editOrder(\'${o.id}\')">Editar</button><button class="btn danger" onclick="event.stopPropagation();deleteOrder(\'${o.id}\')">Excluir</button></div></td></tr>`).join('')}
function filterOrders(){const x=orderFilteredList();ordersBody.innerHTML=ordersRows(x);const box=document.getElementById('orderFilterSummary');if(box)box.innerHTML=orderFilterSummaryHtml(x)}
function formOptions(arr,val=''){return arr.map(x=>`<option value="${esc(x)}" ${x===val?'selected':''}>${esc(x)}</option>`).join('')}
function consultantOptions(val=''){return consultants().map(p=>`<option value="${esc(p.name)}" ${p.name===val?'selected':''}>${esc(p.name)} • ${esc(p.team||'Sem equipe')}</option>`).join('')}
function productOptions(val=''){return products().map(p=>`<option value="${esc(p.name)}" ${p.name===val?'selected':''}>${esc(p.name)}</option>`).join('')}

function monthName(dateStr){
  if(!dateStr)return '';
  const m=Number(String(dateStr).slice(5,7));
  return ['','JANEIRO','FEVEREIRO','MARÇO','ABRIL','MAIO','JUNHO','JULHO','AGOSTO','SETEMBRO','OUTUBRO','NOVEMBRO','DEZEMBRO'][m]||'';
}

function rootStageFallback(o={},stage='cliente'){
  if(stage==='cliente')return {cnpj:o.cnpj||'',razao_social:o.razao_social||'',endereco_instalacao:o.endereco_instalacao||'',cidade:o.cidade||'',representante:o.representante||'',contato:o.contato||'',email:o.email||'',dados_cnpj:o.dados_cnpj||null};
  if(stage==='pedido')return {simulacao:o.simulacao||'',sistema_vivo:o.sistema_vivo||'',status_pedido:o.status_pedido||'ANÁLISE BKO',cotacao:o.cotacao||'',numero_pedido:o.numero_pedido||''};
  if(stage==='entrega')return {data_agendamento:o.data_agendamento||'',status_entrega:o.status_entrega||'',data_entrega:o.data_entrega||'',observacoes:o.observacoes||''};
  if(stage==='finalizacao')return {previsao_comissao:o.previsao_comissao||'',data_conclusao:o.data_conclusao||'',obs_extras:o.obs_extras||''};
  return {};
}
function stageData(item={},o={},stage='',idx=0){const k={cliente:'dados_cliente',pedido:'dados_pedido',entrega:'dados_entrega',finalizacao:'dados_finalizacao'}[stage];return item?.[k]||rootStageFallback(o,stage)}
function addButtonHtml(){return `<button type="button" class="btn primary" onclick="addOrderSet()">+ Adicionar Pedido</button>`}
function clientStageHtml(item={},idx=0,o={}){const d=stageData(item,o,'cliente',idx);return `<div class="stage-item" data-stage="cliente" data-item-index="${idx}" data-cnpj-json='${esc(JSON.stringify(d.dados_cnpj||null))}'><div class="stage-item-head"><b>Pedido ${idx+1}</b><span>Dados do cliente</span></div><div class="form-grid"><div class="field"><label>CNPJ *</label><input data-field="cnpj" value="${esc(d.cnpj||'')}" maxlength="18" oninput="formatCnpjInput(this)" onblur="lookupCnpjForItem(${idx})" required><small data-role="cnpjHint">Digite o CNPJ para buscar os dados automaticamente.</small></div><div class="field span2"><label>Razão Social *</label><input data-field="razao_social" value="${esc(d.razao_social||'')}" required></div><div class="field span2"><label>Endereço / Instalação</label><input data-field="endereco_instalacao" value="${esc(d.endereco_instalacao||'')}"></div><div class="field"><label>Cidade</label><input data-field="cidade" value="${esc(d.cidade||'')}"></div><div class="field"><label>Representante</label><input data-field="representante" value="${esc(d.representante||'')}"></div><div class="field"><label>Contato</label><input data-field="contato" value="${esc(d.contato||'')}"></div><div class="field span2"><label>E-mail</label><input data-field="email" type="email" value="${esc(d.email||'')}"></div></div></div>`}
function commercialItemHtml(item={},idx=0,canRemove=false){const prodOpts=dynamicProductOptions(),subOpts=dynamicSubProductOptions(),subItemOpts=dynamicSubItemOptions();const dash=item.subir_dashboard===true;return `<div class="commercial-item" data-item-index="${idx}"><div class="commercial-item-head"><div><b>Pedido ${idx+1}</b><small>Produto ${idx+1} • informações comerciais</small></div>${canRemove?`<button type="button" class="btn danger" onclick="removeOrderSet(${idx})">Remover pedido</button>`:''}</div><div class="form-grid"><div class="field"><label>Débito automático?</label><select data-field="debito_automatico"><option value="">Selecione</option>${formOptions(['SIM','NÃO'],item.debito_automatico)}</select></div><div class="field"><label>Quality?</label><select data-field="quality"><option value="">Selecione</option>${formOptions(['SIM','NÃO'],item.quality)}</select></div><div class="field"><label>Vencimento</label><select data-field="vencimento"><option value="">Selecionar vencimento</option>${[3,15,17,25].map(v=>`<option value="${v}" ${Number(item.vencimento)===v?'selected':''}>Dia ${String(v).padStart(2,'0')}</option>`).join('')}</select></div><div class="field"><label>Tipo de cliente</label><select data-field="tipo_cliente"><option value="">Selecione</option>${formOptions(['CARTEIRA','COCKPIT'],item.tipo_cliente)}</select></div><div class="field span2"><label>Produto *</label>${renderMultiSelect(`produto_${idx}`,prodOpts,item.produto,'Selecionar produto')}</div><div class="field"><label>Sub Produto</label>${renderMultiSelect(`subproduto_${idx}`,subOpts,item.sub_produto,'Selecionar sub produto')}</div><div class="field"><label>Sub Item</label>${renderMultiSelect(`subitem_${idx}`,subItemOpts,item.sub_item,'Selecionar sub item')}</div><div class="field"><label>Delta</label><input data-field="delta" inputmode="decimal" value="${esc(item.delta||'')}" placeholder="Obrigatório quando for Migração"></div><div class="field"><label>Outro</label><input data-field="outro" value="${esc(item.outro||'')}"></div><div class="field"><label>Quantidade *</label><input data-field="quantidade" type="number" step="0.01" min="0" value="${esc(item.quantidade??1)}" oninput="calcItemTotal(this)"></div><div class="field"><label>Valor unitário</label><input data-field="valor_unitario" type="number" step="0.01" min="0" value="${esc(item.valor_unitario??'')}" oninput="calcItemTotal(this)"></div><div class="field"><label>Valor do contrato / Receita *</label><input data-field="valor_contrato" type="number" step="0.01" min="0" value="${esc(item.valor_contrato??'')}"></div><div class="field"><label>Produto no Dashboard</label><select data-field="dashboard_product"><option value="">Selecione</option>${productOptions(item.dashboard_product)}</select></div><div class="field span2"><label>Pedido ${idx+1} • Adicionar ao Dashboard?</label><input type="hidden" data-field="subir_dashboard" value="${dash?'SIM':'NÃO'}"><div class="dashboard-choice item-dashboard-choice"><button type="button" data-dash="sim" class="${dash?'active':''}" onclick="setItemDashboardChoice(${idx},'SIM')">SIM</button><button type="button" data-dash="nao" class="${dash?'':'active'}" onclick="setItemDashboardChoice(${idx},'NÃO')">NÃO</button></div><small>Somente este pedido/produto será enviado quando estiver marcado como SIM.</small></div></div></div>`}
function orderStageHtml(item={},idx=0,o={}){const d=stageData(item,o,'pedido',idx);return `<div class="stage-item" data-stage="pedido" data-item-index="${idx}"><div class="stage-item-head"><b>Pedido ${idx+1}</b><span>Dados do pedido</span></div><div class="form-grid"><div class="field"><label>Simulação</label><input data-field="simulacao" value="${esc(d.simulacao||'')}"></div><div class="field"><label>Sistema Vivo</label><select data-field="sistema_vivo"><option value="">Selecione</option>${formOptions(['ESTRUTURANTE','VIVOCORP','FENIX','OUTRO'],d.sistema_vivo)}</select></div><div class="field"><label>Status do pedido *</label><select data-field="status_pedido" required>${formOptions(STATUSES,d.status_pedido||'ANÁLISE BKO')}</select></div><div class="field"><label>Cotação</label><input data-field="cotacao" value="${esc(d.cotacao||'')}"></div><div class="field"><label>Nº do pedido</label><input data-field="numero_pedido" value="${esc(d.numero_pedido||'')}"></div></div></div>`}
function deliveryStageHtml(item={},idx=0,o={}){const d=stageData(item,o,'entrega',idx);return `<div class="stage-item" data-stage="entrega" data-item-index="${idx}"><div class="stage-item-head"><b>Pedido ${idx+1}</b><span>Entrega / andamento</span></div><div class="form-grid"><div class="field span2"><label>Data de agendamento</label><input data-field="data_agendamento" value="${esc(d.data_agendamento||'')}" placeholder="Ex.: 24/09/2026 10:30 - 12:30"></div><div class="field"><label>Status de entrega</label><select data-field="status_entrega">${formOptions(DELIVERY,d.status_entrega||'')}</select></div><div class="field"><label>Data de entrega</label><input data-field="data_entrega" type="date" value="${esc(d.data_entrega||'')}"></div><div class="field span4"><label>Observações</label><textarea data-field="observacoes">${esc(d.observacoes||'')}</textarea></div></div></div>`}
function finalStageHtml(item={},idx=0,o={}){const d=stageData(item,o,'finalizacao',idx);return `<div class="stage-item" data-stage="finalizacao" data-item-index="${idx}"><div class="stage-item-head"><b>Pedido ${idx+1}</b><span>Finalização</span></div><div class="form-grid"><div class="field"><label>Previsão de comissão</label><input data-field="previsao_comissao" value="${esc(d.previsao_comissao||'')}" placeholder="Ex.: NOVEMBRO"></div><div class="field"><label>Data de conclusão</label><input data-field="data_conclusao" type="date" value="${esc(d.data_conclusao||'')}"></div><div class="field span4"><label>Observações extras</label><textarea data-field="obs_extras">${esc(d.obs_extras||'')}</textarea></div></div></div>`}
function addOrderSet(){const idx=commercialItemSeq++;document.getElementById('clientItems')?.insertAdjacentHTML('beforeend',clientStageHtml({},idx,{}));document.getElementById('commercialItems')?.insertAdjacentHTML('beforeend',commercialItemHtml({},idx,true));document.getElementById('orderDataItems')?.insertAdjacentHTML('beforeend',orderStageHtml({},idx,{}));document.getElementById('deliveryItems')?.insertAdjacentHTML('beforeend',deliveryStageHtml({},idx,{}));document.getElementById('finalItems')?.insertAdjacentHTML('beforeend',finalStageHtml({},idx,{}));refreshOrderSetLabels();scheduleDraftSave();toast(`Pedido ${document.querySelectorAll('.commercial-item').length} adicionado ✓`)}
function addCommercialItem(){addOrderSet()}
function removeOrderSet(idx){const all=[...document.querySelectorAll('.commercial-item')];if(all.length<=1)return toast('O cadastro precisa ter pelo menos um pedido');['cliente','pedido','entrega','finalizacao'].forEach(stage=>document.querySelector(`.stage-item[data-stage="${stage}"][data-item-index="${idx}"]`)?.remove());document.querySelector(`.commercial-item[data-item-index="${idx}"]`)?.remove();refreshOrderSetLabels();scheduleDraftSave()}
function removeCommercialItem(idx){removeOrderSet(idx)}
function refreshOrderSetLabels(){const products=[...document.querySelectorAll('.commercial-item')];products.forEach((el,pos)=>{const idx=el.dataset.itemIndex;const b=el.querySelector('.commercial-item-head b');if(b)b.textContent=`Pedido ${pos+1}`;const sm=el.querySelector('.commercial-item-head small');if(sm)sm.textContent=`Produto ${pos+1} • informações comerciais`;const lab=[...el.querySelectorAll('label')].find(x=>x.textContent.includes('Adicionar ao Dashboard'));if(lab)lab.textContent=`Pedido ${pos+1} • Adicionar ao Dashboard?`;const rm=el.querySelector('.commercial-item-head .danger');if(rm)rm.style.display=products.length>1?'inline-flex':'none';['cliente','pedido','entrega','finalizacao'].forEach(stage=>{const st=document.querySelector(`.stage-item[data-stage="${stage}"][data-item-index="${idx}"]`);if(st){const sb=st.querySelector('.stage-item-head b');if(sb)sb.textContent=`Pedido ${pos+1}`}})})}
function refreshCommercialRemoveButtons(){refreshOrderSetLabels()}
function setItemDashboardChoice(idx,value){const box=document.querySelector(`.commercial-item[data-item-index="${idx}"]`);if(!box)return;const hidden=box.querySelector('[data-field="subir_dashboard"]');if(hidden)hidden.value=value;box.querySelector('[data-dash="sim"]')?.classList.toggle('active',value==='SIM');box.querySelector('[data-dash="nao"]')?.classList.toggle('active',value!=='SIM');scheduleDraftSave()}
function calcItemTotal(el){const box=el.closest('.commercial-item');if(!box)return;const q=parseNum(box.querySelector('[data-field="quantidade"]')?.value),u=parseNum(box.querySelector('[data-field="valor_unitario"]')?.value),total=box.querySelector('[data-field="valor_contrato"]');if(q&&u&&total)total.value=(q*u).toFixed(2);scheduleDraftSave()}
function stageBox(idx,stage){return document.querySelector(`.stage-item[data-stage="${stage}"][data-item-index="${idx}"]`)}
function collectStageData(idx,stage){const el=stageBox(idx,stage);if(!el)return{};const f=n=>el.querySelector(`[data-field="${n}"]`)?.value??'';if(stage==='cliente'){let dados_cnpj=null;try{dados_cnpj=JSON.parse(el.dataset.cnpjJson||'null')}catch{}return{cnpj:cleanCnpj(f('cnpj')),razao_social:f('razao_social').trim(),endereco_instalacao:f('endereco_instalacao').trim(),cidade:f('cidade').trim(),representante:f('representante').trim(),contato:f('contato').trim(),email:f('email').trim(),dados_cnpj}}if(stage==='pedido')return{simulacao:f('simulacao').trim(),sistema_vivo:f('sistema_vivo'),status_pedido:f('status_pedido'),cotacao:f('cotacao').trim(),numero_pedido:f('numero_pedido').trim()};if(stage==='entrega')return{data_agendamento:f('data_agendamento').trim(),status_entrega:f('status_entrega'),data_entrega:f('data_entrega'),observacoes:f('observacoes').trim()};if(stage==='finalizacao')return{previsao_comissao:f('previsao_comissao').trim(),data_conclusao:f('data_conclusao'),obs_extras:f('obs_extras').trim()};return{}}
async function lookupCnpjForItem(idx){const box=stageBox(idx,'cliente');if(!box)return;const f=n=>box.querySelector(`[data-field="${n}"]`);const c=cleanCnpj(f('cnpj')?.value);const hint=box.querySelector('[data-role="cnpjHint"]');if(c.length!==14){if(hint)hint.textContent='CNPJ deve ter 14 dígitos.';return}if(hint)hint.textContent='Consultando CNPJ...';const local=clients.find(x=>cleanCnpj(x.cnpj)===c);try{const result=await fetchCnpjData(c);const b=result.data||{};const arr=v=>Array.isArray(v)?v:(v&&typeof v==='object'?Object.values(v):[]);const qsa=[b.qsa,b.socios,b.quadro_societario,b.administradores].flatMap(arr).filter(Boolean);const rep=qsa[0]||{};const d={razao_social:firstText(b.razao_social,b.nome_empresarial,b.nome),endereco:joinAddress([firstText(b.logradouro,b.street,b.endereco),firstText(b.numero),firstText(b.complemento)]),cidade:firstText(b.municipio,b.cidade,b.city,b.localidade),representante:firstText(b.representante_normalizado,b.nome_representante_legal,b.representante,b.responsavel,rep.nome_socio,rep.nome,rep.name),telefone:formatPhone(firstText(b.ddd_telefone_1,b.ddd_telefone_2,b.telefone,b.phone)),email:firstText(b.email,b.correio_eletronico),fonte_consulta:result.source||''};if(!d.razao_social&&local?.razao_social)d.razao_social=local.razao_social;if(local?.dados_cnpj)d={...local.dados_cnpj,...d};box.dataset.cnpjJson=JSON.stringify(d);if(d.razao_social)f('razao_social').value=d.razao_social;if(d.endereco)f('endereco_instalacao').value=d.endereco;if(d.cidade)f('cidade').value=d.cidade;if(d.representante)f('representante').value=d.representante;if(d.telefone)f('contato').value=d.telefone;if(d.email)f('email').value=d.email;if(hint)hint.textContent=`Dados do CNPJ preenchidos automaticamente ✓${d.fonte_consulta?' ('+d.fonte_consulta+')':''}`;scheduleDraftSave()}catch(e){if(local){if(local.razao_social)f('razao_social').value=local.razao_social;if(local.dados_cnpj)box.dataset.cnpjJson=JSON.stringify(local.dados_cnpj);if(hint)hint.textContent='Cliente encontrado na base ✓'}else if(hint)hint.textContent='Não foi possível consultar agora. Você pode preencher manualmente.'}}
function collectCommercialItems(validate=true){const items=[...document.querySelectorAll('.commercial-item')].map(el=>{const idx=el.dataset.itemIndex;const f=n=>el.querySelector(`[data-field="${n}"]`)?.value??'';return {debito_automatico:f('debito_automatico')||null,quality:f('quality')||null,vencimento:f('vencimento')?Number(f('vencimento')):null,tipo_cliente:f('tipo_cliente')||null,produto:multiSelectValues(`produto_${idx}`),sub_produto:multiSelectValues(`subproduto_${idx}`),sub_item:multiSelectValues(`subitem_${idx}`),delta:f('delta').trim()||null,outro:f('outro').trim()||null,quantidade:parseNum(f('quantidade')),valor_unitario:f('valor_unitario')===''?null:parseNum(f('valor_unitario')),valor_contrato:parseNum(f('valor_contrato')),dashboard_product:f('dashboard_product'),subir_dashboard:f('subir_dashboard')==='SIM',dados_cliente:collectStageData(idx,'cliente'),dados_pedido:collectStageData(idx,'pedido'),dados_entrega:collectStageData(idx,'entrega'),dados_finalizacao:collectStageData(idx,'finalizacao')}});if(validate){for(let i=0;i<items.length;i++){const it=items[i];if(it.dados_cliente.cnpj.length!==14)throw new Error(`Confira o CNPJ do Pedido ${i+1}`);if(!it.dados_cliente.razao_social)throw new Error(`Informe a Razão Social do Pedido ${i+1}`);if(!it.produto.length)throw new Error(`Selecione o Produto ${i+1}`);if(it.subir_dashboard&&!it.dashboard_product)throw new Error(`Selecione o Produto no Dashboard do Pedido ${i+1}`);if(itemIsMigration(it)&&!String(it.delta??'').trim())throw new Error(`Informe o Delta do Produto ${i+1} (Migração)`);if(![3,15,17,25].includes(Number(it.vencimento)))throw new Error(`Selecione o vencimento do Produto ${i+1}`)}}return items}
